def to_roman(n: int) -> str:
    if not 1 <= n <= 3999:
        raise ValueError("n must be between 1 and 3999")

    val = [
        1000, 900, 500, 400,
        100, 90, 50, 40,
        10, 9, 5, 4,
        1
    ]
    syms = [
        "M", "CM", "D", "CD",
        "C", "XC", "L", "XL",
        "X", "IX", "V", "IV",
        "I"
    ]

    roman = []
    for v, s in zip(val, syms):
        while n >= v:
            roman.append(s)
            n -= v
    return "".join(roman)


def from_roman(s: str) -> int:
    if not s or not s.isupper():
        raise ValueError("Invalid Roman numeral")

    values = {
        'I': 1,
        'V': 5,
        'X': 10,
        'L': 50,
        'C': 100,
        'D': 500,
        'M': 1000
    }

    total = 0
    prev_value = 0

    for ch in reversed(s):
        if ch not in values:
            raise ValueError("Invalid Roman numeral")
        curr_value = values[ch]
        if curr_value < prev_value:
            total -= curr_value
        else:
            total += curr_value
        prev_value = curr_value

    # Optional validation: ensure conversion back matches
    if to_roman(total) != s:
        raise ValueError("Invalid Roman numeral")

    return total

