def evaluate(expr: str) -> float:
    def parse_number(i):
        start = i
        while i < len(expr) and (expr[i].isdigit() or expr[i] == '.'):
            i += 1
        return float(expr[start:i]), i

    def parse_factor(i):
        if i >= len(expr):
            raise ValueError("Unexpected end")
        if expr[i] == '(':
            val, i = parse_expr(i + 1)
            if i >= len(expr) or expr[i] != ')':
                raise ValueError("Missing )")
            return val, i + 1
        if expr[i] == '-':
            val, i = parse_factor(i + 1)
            return -val, i
        if expr[i] == '+':
            return parse_factor(i + 1)
        return parse_number(i)

    def parse_term(i):
        val, i = parse_factor(i)
        while i < len(expr) and expr[i] in '*/':
            op = expr[i]
            rhs, i = parse_factor(i + 1)
            if op == '*':
                val *= rhs
            else:
                val /= rhs
        return val, i

    def parse_expr(i):
        val, i = parse_term(i)
        while i < len(expr) and expr[i] in '+-':
            op = expr[i]
            rhs, i = parse_term(i + 1)
            if op == '+':
                val += rhs
            else:
                val -= rhs
        return val, i

    expr = expr.replace(' ', '')
    result, index = parse_expr(0)
    if index != len(expr):
        raise ValueError("Unexpected character")
    return result

