def word_break(s: str, words: list) -> str:
    if not s:
        return ""

    word_set = set(words)
    n = len(s)
    dp = [False] * (n + 1)
    dp[0] = True

    for i in range(1, n + 1):
        for j in range(i):
            if dp[j] and s[j:i] in word_set:
                dp[i] = True
                break

    if not dp[n]:
        return ""

    result = []
    i = n
    while i > 0:
        for j in range(i - 1, -1, -1):
            if dp[j] and s[j:i] in word_set:
                result.append(s[j:i])
                i = j
                break

    return " ".join(reversed(result))

