def flatten(obj, sep='.'):
    # Dict kosong di root -> {}
    if not obj:
        return {}

    result = {}

    def _walk(value, prefix):
        if isinstance(value, dict):
            if not value:
                # Dict kosong DI DALAM -> simpan apa adanya
                result[prefix] = {}
                return
            for key, sub in value.items():
                new_prefix = f"{prefix}{sep}{key}" if prefix else str(key)
                _walk(sub, new_prefix)
        else:
            # Nilai non-dict dipertahankan apa adanya
            result[prefix] = value

    for key, value in obj.items():
        _walk(value, str(key))

    return result

