def evaluate(expr: str) -> float:
    """
    Evaluate an arithmetic expression with +, -, *, /, parentheses,
    integers/decimals, and unary minus. Spaces are ignored.
    Division uses normal float division. Expression is assumed valid.
    """
    tokens = []
    i = 0
    n = len(expr)
    while i < n:
        c = expr[i]
        if c.isspace():
            i += 1
            continue
        if c in '+-*/()':
            tokens.append(c)
            i += 1
        elif c.isdigit() or c == '.':
            j = i
            while j < n and (expr[j].isdigit() or expr[j] == '.'):
                j += 1
            tokens.append(expr[i:j])
            i = j
        else:
            raise ValueError(f"Unexpected character: {c!r}")

    pos = 0

    def peek():
        return tokens[pos] if pos < len(tokens) else None

    def consume():
        nonlocal pos
        t = tokens[pos]
        pos += 1
        return t

    def parse_number_or_paren():
        """Parse a primary: number, unary minus applied to primary, or parenthesized expr."""
        t = peek()
        if t == '-':
            consume()
            # unary minus binds to the next primary (right associativity of unary)
            return -parse_number_or_paren()
        if t == '+':
            consume()
            return parse_number_or_paren()
        if t == '(':
            consume()
            val = parse_expr()
            if peek() != ')':
                raise ValueError("Missing closing parenthesis")
            consume()
            return val
        if t is None:
            raise ValueError("Unexpected end of expression")
        # otherwise must be a number literal
        consume()
        return float(t)

    def parse_term():
        """Handle *, / with left associativity."""
        val = parse_number_or_paren()
        while True:
            t = peek()
            if t == '*':
                consume()
                val *= parse_number_or_paren()
            elif t == '/':
                consume()
                val /= parse_number_or_paren()
            else:
                break
        return val

    def parse_expr():
        """Handle +, - with left associativity."""
        val = parse_term()
        while True:
            t = peek()
            if t == '+':
                consume()
                val += parse_term()
            elif t == '-':
                consume()
                val -= parse_term()
            else:
                break
        return val

    result = parse_expr()
    if pos != len(tokens):
        raise ValueError("Unexpected trailing tokens")
    return result


