def word_break(s: str, words: list) -> str:
    if not s:
        return ''  # string kosong -> tidak ada yang perlu dipenggal

    word_set = set(words)
    n = len(s)

    # memo[i] menyimpan cara memenggal s[i:] (None = belum dihitung)
    memo = {}

    def solve(i: int):
        if i == n:
            return ''          # base case: berhasil sampai akhir
        if i in memo:
            return memo[i]

        for j in range(i + 1, n + 1):
            chunk = s[i:j]
            if chunk in word_set:
                rest = solve(j)
                if rest is not None:          # ada solusi untuk sisa
                    result = chunk if rest == '' else chunk + ' ' + rest
                    memo[i] = result
                    return result

        memo[i] = None       # tidak ada cara memenggal dari i
        return None

    ans = solve(0)
    return ans if ans is not None else ''
